class Notice{
    constructor(){
        var _this = this;

        this.m2_swpier = null;
        this.bItemList = [];

        axios.get("/api/popups").then(function(r){
            var closedPopupList = _this.getCookie("closedPopupList");
            closedPopupList = closedPopupList != null ? closedPopupList.split("&") : [];

            r.data.content.forEach(function(e, i){
                if(!closedPopupList.includes(e.id)){
                    _this.popupListView.itemList.push({
                        id: e.id,
                        path: e.path,
                        link: e.link,
                        x: e.x,
                        y: e.y
                    });
                }
            });
        });

        this.popupListView = new Vue({
            el: ".popup-list",
            data: {
                itemList: []
            },
            methods: {
                requestLink: function(i){
                    window.open(this.itemList[i].link, "_blank");
                },
                requestClose: function(i){
                    this.itemList.splice(i, 1);
                },
                requestCloseDay: function(i){
                    var closedPopupList = _this.getCookie("closedPopupList");
                    closedPopupList = closedPopupList != null ? closedPopupList.split("&") : [];
                    closedPopupList.push(this.itemList[i].id);
                    _this.setCookie("closedPopupList", closedPopupList.join("&"), {expires: (new Date(dayjs().format("YYYY-MM-DD 23:59:59"))).toUTCString()});
                    this.itemList.splice(i, 1);
