                }
            }
        });

        this.pagenationView = new Vue({
            el: ".employment-pagenation",
            data: {
                currentPage: _this.page,
                lastPage: 0,
                itemList: []
            },
            methods: {
                requestGoingPrevPage: function(){
                    this.requestGoingPage(this.currentPage - 1);
                },
                requestGoingNextPage: function(){
                    if(this.currentPage + 1 > this.lastPage) return;
                    this.requestGoingPage(this.currentPage + 1);
                },
                requestGoingPage: function(i){
                    _this.getEmploymentList(i, _this.searchView.keyword);
                    document.querySelector(".employment-list").scrollIntoView({behavior : 'smooth', block: "center"});
                }
            }
        });

        this.getEmploymentList(_this.page);
    }

    getEmploymentList(page, keyword){
        var _this = this;
        axios.get("/api/notices", {
            params: {
                page: page,
                keyword: keyword,
                category: ["채용"]
            }
        }).then(function(r){
            _this.pagenationView.itemList = [];
            _this.employmentListView.itemList = [];

            _this.summaryView.count = r.data.totalElements;

            _this.pagenationView.currentPage = r.data.number;
            _this.pagenationView.lastPage = r.data.totalPages - 1;
            for(let i = Math.floor(r.data.number / 5) * 5; i < r.data.totalPages && i < (Math.floor(r.data.number / 5) * 5) + 5; i++){
                _this.pagenationView.itemList.push(i);
            }

            r.data.content.forEach((e, i) => {
                _this.employmentListView.itemList.push({
                    number: r.data.totalElements - ((r.data.number * r.data.size) + i),
                    id: e.id,
                    title: e.title,
                    category: e.category,
                    state: e.state,
                    notice: e.notice,
                    hit: e.hit,
                    file: e.filePath != null,
                    registrationDatetime: e.registrationDatetime.split(" ")[0]
                });
            });
            history.pushState(null, null, '?page=' + page);
        });
    }
}

